            this.hysteriaCool = pCompound.getInt("HysteriaCool");
        }
        if (pCompound.contains("MeleeCool")) {
            this.meleeCool = pCompound.getInt("MeleeCool");
        }
        if (pCompound.contains("SpellType")) {
            this.spellType = pCompound.getInt("SpellType");
        }
        if (pCompound.contains("HitTimes")) {
            this.hitTimes = pCompound.getInt("HitTimes");
        }
        if (pCompound.contains("LastHitTime")) {
            this.lastHitTime = pCompound.getInt("LastHitTime");
        }
        if (pCompound.contains("Overwhelmed")) {
            this.overwhelmed = pCompound.getInt("overwhelmed");
        }
        if (this.hasCustomName()) {
            this.bossInfo.setName(this.getDisplayName());
        }
    }

@Override
    protected void actuallyHurt(ServerLevel level, DamageSource source, float amount) {
        LivingEntity livingentity = this.getTarget();
        if (livingentity != null
                && (double) this.random.nextFloat() < this.getAttributeValue(Attributes.SPAWN_REINFORCEMENTS_CHANCE)
                && level.getGameRules().get(GameRules.SPAWN_MOBS)) {

            long currentGameTime = level.getGameTime();

            // Reset the counter if the time window has passed
            synchronized (PossessedBeeEntity.class) {
                if (currentGameTime - lastResetGameTime > TIME_WINDOW_TICKS) {
                    beeSpawnCounter.set(0);
                    lastResetGameTime = currentGameTime;
                }
            }

            // Check if the spawn limit has been reached
            if (beeSpawnCounter.get() < MAX_BEES_PER_TIME) {
                Bee bee = OccultismEntities.POSSESSED_BEE.get().create(level, EntitySpawnReason.REINFORCEMENT);
                double offsetX = level.getRandom().nextGaussian() * (1 + level.getRandom().nextInt(4));
                double offsetZ = level.getRandom().nextGaussian() * (1 + level.getRandom().nextInt(4));
                bee.snapTo(this.getBlockX() + offsetX, this.getBlockY() + 1.5, this.getBlockZ() + offsetZ, level.getRandom().nextInt(360), 0);
                level.addFreshEntity(bee);

                // Increment the counter
                beeSpawnCounter.incrementAndGet();
            }
        }
        super.actuallyHurt(level, source, amount);
    }

@Override
    public boolean doHurtTarget(ServerLevel serverLevel, Entity entity) {
        DamageSource damagesource = this.damageSources().sting(this);
        boolean flag = entity.hurtServer(serverLevel, damagesource, (float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE)));
        if (flag) {
            if (this.level() instanceof ServerLevel serverlevel) {
                EnchantmentHelper.doPostAttackEffects(serverlevel, entity, damagesource);
            }

            if (entity instanceof LivingEntity livingentity) {
                livingentity.setStingerCount(livingentity.getStingerCount() + 1);
                int i = 10;
                if (this.level().getDifficulty() == Difficulty.NORMAL) {
                    i = 20;
                } else if (this.level().getDifficulty() == Difficulty.HARD) {
                    i = 30;
                }
                livingentity.addEffect(new MobEffectInstance(MobEffects.POISON, i * 20, 0), this);
            }

            this.playSound(SoundEvents.BEE_STING, 1.0F, 1.0F);
        }

        return flag;
    }

@Override
    protected void checkAndPerformAttack(ToyBase target) {
        long currentTime = dino.level.getGameTime();
        if (attackType == GRAB) {
            for (Entity passenger : swimming.getPassengers()) {
                if (passenger instanceof ToyBase toy && currentTime == grabStartTick + GRAB_DURATION) {
                    swimming.stopGrabAttack(passenger);
                    swimming.moodSystem.setToyTarget(null);
                    swimming.moodSystem.useToy(toy.moodBonus);
                }
            }
        } else if (attackType == ATTACK) {
            if (attackDamageTick > 0 && currentTime >= attackDamageTick) {
                target.hurt(DamageSource.mobAttack(dino), 0);
                attackDamageTick = -1;
                attackType = -1;
            }
        } else if (currentTime > attackEndTick + 20 && Util.canReachPrey(dino, target)) {
            boolean tooBig = !Util.isEntitySmallerThan(target, 2 * swimming.getScale() / swimming.data().maxScale());
            if (swimming.aiAttackType() != Attacking.GRAB || tooBig || swimming.getRandom().nextInt(5) > 0) {
                attackType = ATTACK;
                ServerAnimationInfo animationInfo = dino.startAttack();
                attackDamageTick = (long) (currentTime + animationInfo.actionDelay);
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
            } else {
                attackType = GRAB;
                swimming.startGrabAttack(target);
                attackEndTick = 1;
                grabStartTick = currentTime;
            }
        }
    }

@Override
    public boolean canContinueToUse() {
        if (attackType == GRAB && !swimming.isDoingGrabAttack()) {
            return false;
        }
        return super.canContinueToUse();
    }

@Override
    public void start() {
        super.start();
        attackType = -1;
        grabStartTick = -1;
    }

@Override
    public void tick() {
        if (attackType != GRAB) {
            dino.getLookControl().setLookAt(target, 30, 30);
            if (dino.getNavigation().isDone() && !Util.canReachPrey(dino, target)) {
                dino.getNavigation().moveTo(target, speedModifier);
            }
        }
        checkAndPerformAttack(target);
    }

@Override
    public boolean canUse() {
        long l = dino.level.getGameTime();
        if (l - lastCanUseCheck < COOLDOWN_BETWEEN_CAN_USE_CHECKS) {
            return false;
        }
        lastCanUseCheck = l;
        if (dino.isFleeing() || dino.getTarget() != null || dino.getCurrentOrder() != OrderType.WANDER) {
            return false;
        }
        if (dino.moodSystem.getPlayingCooldown() > 0 || dino.moodSystem.getMood() >= 100) {
            return false;
        }
        target = findPlayTarget();
        if (target == null) {
            return false;
        }
        path = dino.getNavigation().createPath(target, 0);
        if (path != null) {
            return true;
        }
        return Util.canReachPrey(dino, target);
    }

@Override
    public boolean canContinueToUse() {
        if (dino.level.getGameTime() < attackEndTick) {
            //Prevent the goal from ending before the animation is over
            return true;
        }
        ToyBase currentToyTarget = dino.moodSystem.getToyTarget();
        if (currentToyTarget == null) {
            currentToyTarget = target;
        }
        if (currentToyTarget == null || dino.moodSystem.getPlayingCooldown() > 0) {
            return false;
        }
        double d = getFollowDistance();
        if (dino.distanceToSqr(currentToyTarget) > d * d || dino.getCurrentOrder() != OrderType.WANDER) {
            return false;
        }
        dino.moodSystem.setToyTarget(currentToyTarget);
        return true;
    }

